// ===== src/vm/bytecode.rs =====

#[derive(Debug, Clone)]
pub enum Value {
    // Primitive
    Int(i64),
    Bool(bool),
    Float(f64),
    None,

    Object(Rc<Object>),
}

impl PartialEq for Value {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Value::Int(a), Value::Int(b)) => a == b,
            (Value::Bool(a), Value::Bool(b)) => a == b,
            (Value::Float(a), Value::Float(b)) => a == b,
            (Value::Int(a), Value::Float(b)) => *a as f64 == *b,
            (Value::Float(a), Value::Int(b)) => *a == *b as f64,
            (Value::None, Value::None) => true,
            (Value::Object(a), Value::Object(b)) => {
                if Rc::ptr_eq(a, b) {
                    return true;
                }
                // String은 값 비교
                // TODO: __eq__ 메서드 구현 필요
                match (&a.data, &b.data) {
                    (ObjectData::String(s1), ObjectData::String(s2)) => s1 == s2,
                    // 다른 객체들은 포인터 비교만 (identity)
                    _ => false,
                }
            }
            _ => false,
        }
    }
}

impl Eq for Value {}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ClassDef {
    pub name: String,
    pub methods: HashMap<String, u16>, // method_name → function_id
                                       // 나중에: base_class: Option<u16> (상속)
}

#[derive(Debug, Clone, PartialEq)]
pub enum Instruction {
    // constants
    ConstI64(i64),  // Push constant value onto stack
    ConstF64(f64),
    ConstStr(u32),
    True,
    False,
    None,
    LoadConst(u32), // Load constant from consts array

    // stack operations
    Pop,
    /// 스택 top 값을 복제
    /// Stack: value → value, value
    Dup,

    // locals/globals
    LoadLocal(u16),
    StoreLocal(u16),
    LoadGlobal(u16),
    StoreGlobal(u16),

    // arithmetic
    Add,
    Sub,
    Mul,
    Div,     // Floor division (//)
    TrueDiv, // True division (/)
    Mod,
    Neg,
    Pos,

    // compare/logical
    Eq,
    Ne,
    Lt,
    Le,
    Gt,
    Ge,
    Not,

    // control flow
    Jump(i32),
    JumpIfFalse(i32),
    JumpIfTrue(i32),

    // call/return
    Call(u16 /* func_id */, u8 /* argc */),
    CallBuiltin(u8 /* builtin_id */, u8 /* argc */),
    Return,

    /// 값을 callable로 호출 (func가 스택에 있음)
    /// Stack: callable, arg1, arg2, ... → result
    CallValue(u8 /* argc */),

    /// 메서드 호출: receiver.method(args)
    /// Stack: receiver, arg1, arg2, ... → result
    CallMethod(u16 /* method_name_sym */, u8 /* argc */),

    /// Attribute 로드: obj.attr
    /// Stack: object → value
    LoadAttr(u16 /* attr_name_sym */),

    /// Attribute 저장: obj.attr = value
    /// Stack: object, value →
    StoreAttr(u16 /* attr_name_sym */),

    /// 리스트 생성: 스택에서 n개의 값을 꺼내 리스트 생성
    /// Stack: val1, val2, ..., valn → list
    BuildList(u16 /* count */),

    /// 튜플 생성: 스택에서 n개의 값을 꺼내 튜플 생성
    /// Stack: val1, val2, ..., valn → tuple
    BuildTuple(u16 /* count */),

    /// 딕셔너리 생성: 스택에서 2n개의 값을 꺼내 딕셔너리 생성
    /// Stack: key1, val1, key2, val2, ..., keyn, valn → dict
    BuildDict(u16 /* pair_count */),

    /// Set 생성: 스택에서 n개의 값을 꺼내 Set 생성
    /// Stack: val1, val2, ..., valn → set
    BuildSet(u16 /* count */),

    /// TreeSet 생성: 스택에서 n개의 값을 꺼내 TreeSet 생성
    /// Stack: val1, val2, ..., valn → treeset
    BuildTreeSet(u16 /* count */),

    /// 인덱스 로드: obj[idx]
    /// Stack: object, index → value
    LoadIndex,

    /// 인덱스 저장: obj[idx] = value
    /// Stack: object, index, value →
    StoreIndex,

    /// Create a closure/lambda at runtime
    /// Pops num_captures values from stack (captured variables)
    /// Pushes a callable function object
    /// Stack: capture1, capture2, ..., captureN → function_object
    MakeClosure(u16 /* func_id */, u8 /* num_captures */),
}

#[derive(Debug, Clone)]
pub struct FunctionCode {
    pub name_sym: u16,
    pub arity: u8,
    pub num_locals: u16,
    pub code: Vec<Instruction>,
}

#[derive(Debug, Clone)]
pub struct Module {
    /// 상수 풀
    pub consts: Vec<Value>,

    /// 문자열 풀 (문자열 리터럴)
    pub string_pool: Vec<String>,

    /// 전역 변수 슬롯
    pub globals: Vec<Option<Value>>,

    /// 심볼 테이블 (변수/함수 이름)
    pub symbols: Vec<String>,

    /// 함수 코드 목록
    pub functions: Vec<FunctionCode>,

    /// 사용자 정의 클래스 목록
    pub classes: Vec<ClassDef>,

    /// 타입 테이블 (builtin + user-defined)
    ///
    /// 인덱스 0-99는 builtin 타입, 100+는 사용자 정의 타입
    pub types: Vec<TypeDef>,
}

impl Default for Module {
    fn default() -> Self {
        Self::new()
    }
}

impl Module {
    /// 새 모듈 생성 및 builtin 타입 초기화
    ///
    /// 8개의 builtin 타입(int, bool, str, NoneType, range, list, dict, float)을 자동으로 초기화합니다.
    /// 타입 정의는 `type_def::init_builtin_types()`에서 가져옵니다.
    pub fn new() -> Self {
        Module {
            consts: Vec::new(),
            string_pool: Vec::new(),
            globals: Vec::new(),
            symbols: Vec::new(),
            functions: Vec::new(),
            classes: Vec::new(),
            types: init_builtin_types(),
        }
    }
}



// ===== src/vm/value.rs =====
// # 설계 원칙
//
// 1. **모든 것은 객체다**: String도 Object, 클래스도 Object
// 2. **타입 테이블 기반**: 각 Object는 `type_id`로 타입을 참조
// 3. **속성 지연 할당**: 필요한 경우에만 `attributes` HashMap 할당 (메모리 최적화)



/// 통일된 런타임 객체
///
/// Python의 PyObject에 해당합니다. 모든 heap-allocated 값은 이 구조체로 표현됩니다.
///
/// # 메모리 레이아웃
///
/// - `type_id`: 2 bytes (타입 테이블 인덱스)
/// - `data`: 8-24 bytes (ObjectData enum)
/// - `attributes`: 16 bytes (Option<RefCell<HashMap>>)
///
/// 총 ~26-42 bytes + heap data
#[derive(Debug, Clone)]
pub struct Object {
    /// 타입 ID (Module.types 테이블의 인덱스)
    /// 예: TYPE_STR (2), TYPE_RANGE (4), 또는 사용자 정의 타입 (100+)
    pub type_id: u16,

    /// 객체의 실제 데이터
    pub data: ObjectData,

    /// 인스턴스 속성 (__dict__)
    pub attributes: Option<RefCell<HashMap<String, Value>>>,
}

impl Object {
    /// 새 객체 생성 (속성 없이)
    pub fn new(type_id: u16, data: ObjectData) -> Self {
        Self {
            type_id,
            data,
            attributes: None,
        }
    }

    /// 속성을 가질 수 있는 객체 생성
    pub fn new_with_attrs(type_id: u16, data: ObjectData) -> Self {
        Self {
            type_id,
            data,
            attributes: Some(RefCell::new(HashMap::new())),
        }
    }

    pub fn get_attr(&self, name: &str) -> Option<Value> {
        self.attributes
            .as_ref()
            .and_then(|attrs| attrs.borrow().get(name).cloned())
    }

    pub fn set_attr(&mut self, name: String, value: Value) {
        if self.attributes.is_none() {
            self.attributes = Some(RefCell::new(HashMap::new()));
        }
        if let Some(ref attrs) = self.attributes {
            attrs.borrow_mut().insert(name, value);
        }
    }
}

#[derive(Debug, Clone)]
pub enum ObjectData {
    String(String),

    /// List (mutable)
    List {
        items: RefCell<Vec<Value>>,
    },

    /// Tuple (immutable)
    Tuple {
        items: Vec<Value>,
    },

    /// Dict (mutable)
    Dict {
        map: RefCell<HashMap<DictKey, Value>>,
    },

    /// Set (mutable, HashSet)
    Set {
        items: RefCell<HashSet<SetKey>>,
    },

    /// TreeSet (mutable, BTreeSet)
    TreeSet {
        items: RefCell<BTreeSet<SetKey>>,
    },

    /// 사용자 정의 클래스
    UserClass {
        class_id: u16,
        methods: HashMap<String, u16>, // method_name -> func_id
    },

    /// 사용자 정의 객체 인스턴스
    UserInstance {
        class_id: u16,
    },

    /// Builtin 클래스
    BuiltinClass {
        class_type: BuiltinClassType,
    },

    /// Builtin 인스턴스
    BuiltinInstance {
        class_type: BuiltinClassType,
        data: BuiltinInstanceData,
    },

    /// User-defined function/lambda (closure)
    UserFunction {
        func_id: u16,
        captures: Vec<Value>,
    },
}

/// Dict key wrapper (hashable types only)
/// TODO: __hash__ 메서드 구현 시 가능하도록 수정 필요
#[derive(Debug, Clone, Hash, Eq, PartialEq)]
pub enum DictKey {
    Int(i64),
    String(String),
    Bool(bool),
}

/// Set key wrapper (hashable and orderable types)
/// Used for both HashSet and BTreeSet
#[derive(Debug, Clone, Hash, Eq, PartialEq, Ord, PartialOrd)]
pub enum SetKey {
    Int(i64),
    String(String),
    Bool(bool),
}

#[derive(Debug, Clone)]
pub enum BuiltinInstanceData {
    /// Range iterator 상태
    Range {
        current: RefCell<i64>,
        stop: i64,
        step: i64,
    },

    /// List iterator 상태
    ListIterator {
        items: Rc<RefCell<Vec<Value>>>,
        current: RefCell<usize>,
    },

    /// Dict iterator 상태 (keys iterator)
    DictIterator {
        keys: Vec<DictKey>,
        current: RefCell<usize>,
    },

    /// Map iterator 상태
    MapIterator {
        func: Box<Value>,
        source_iter: Box<Value>,
    },

    /// Filter iterator 상태
    FilterIterator {
        func: Box<Value>,
        source_iter: Box<Value>,
        /// 미리 찾아둔 다음 값 (peek buffer)
        peeked: std::cell::RefCell<Option<Value>>,
    },

    /// Set iterator 상태
    SetIterator {
        keys: Vec<SetKey>,
        current: RefCell<usize>,
    },

    /// TreeSet iterator 상태
    TreeSetIterator {
        keys: Vec<SetKey>,
        current: RefCell<usize>,
    },
}



// ===== src/runtime_io.rs =====

/// Result type for read operations
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ReadResult {
    /// Successfully read a line
    Ok(String),
    /// Waiting for input (e.g., web/interactive)
    WaitingForInput,
    /// Error occurred
    Error(String),
}

/// Abstraction over runtime I/O so the VM can remain pure w.r.t. environment.
pub trait RuntimeIo {
    fn write_line(&mut self, s: &str);
    fn write(&mut self, s: &str);
    fn read_line(&mut self) -> ReadResult;
    fn read_line_with_prompt(&mut self, prompt: Option<&str>) -> ReadResult;
}

/// Default I/O that talks to process stdout/stdin (CLI use).
pub struct StdIo;

impl RuntimeIo for StdIo {
    fn write_line(&mut self, s: &str) {
        println!("{}", s);
    }
    fn write(&mut self, s: &str) {
        print!("{}", s);
        let _ = std::io::stdout().flush();
    }
    fn read_line(&mut self) -> ReadResult {
        let stdin = io::stdin();
        let mut line = String::new();
        match stdin.lock().read_line(&mut line) {
            Ok(_) => ReadResult::Ok(line.trim_end().to_string()),
            Err(e) => ReadResult::Error(e.to_string()),
        }
    }
    fn read_line_with_prompt(&mut self, prompt: Option<&str>) -> ReadResult {
        if let Some(p) = prompt {
            self.write(p);
        }
        self.read_line()
    }
}

/// Buffer-based I/O for browsers/tests: caller pushes input, we accumulate output.
pub struct BufferIo {
    output: String,
    input: VecDeque<String>,
    last_prompt: Option<String>,
}

impl BufferIo {
    pub fn new() -> Self {
        Self {
            output: String::new(),
            input: VecDeque::new(),
            last_prompt: None,
        }
    }
    pub fn push_input_line<S: Into<String>>(&mut self, line: S) {
        self.input.push_back(line.into());
    }
    pub fn take_output(self) -> String {
        self.output
    }
    pub fn get_output(&self) -> &str {
        &self.output
    }
    pub fn drain_output(&mut self) -> String {
        std::mem::take(&mut self.output)
    }
    pub fn clear_output(&mut self) {
        self.output.clear();
    }
}

impl Default for BufferIo {
    fn default() -> Self {
        Self::new()
    }
}

impl RuntimeIo for BufferIo {
    fn write_line(&mut self, s: &str) {
        self.output.push_str(s);
        self.output.push('\n');
    }
    fn write(&mut self, s: &str) {
        self.output.push_str(s);
    }
    fn read_line(&mut self) -> ReadResult {
        if let Some(line) = self.input.pop_front() {
            ReadResult::Ok(line)
        } else {
            ReadResult::WaitingForInput
        }
    }
    fn read_line_with_prompt(&mut self, prompt: Option<&str>) -> ReadResult {
        // Show prompt only if it's different from last time (prevents duplicate on retry)
        if let Some(p) = prompt
            && self.last_prompt.as_deref() != Some(p)
        {
            self.write(p);
            self.last_prompt = Some(p.to_string());
        }

        match self.read_line() {
            ReadResult::Ok(line) => {
                // Clear last_prompt after successful read
                self.last_prompt = None;
                ReadResult::Ok(line)
            }
            other => other,
        }
    }
}


// ===== src/vm/utils.rs =====
// VM 유틸리티 함수
//
// Value 표시, 타입 이름, 동등성 비교 등 VM에서 공통적으로 사용되는 헬퍼 함수들을 제공합니다.


/// Value를 출력 가능한 문자열로 변환
///
/// Python의 `str()` 표현과 유사하게 값을 문자열로 변환합니다.
///
/// # Examples
///
/// ```ignore
/// display_value(&Value::Int(42))        // → "42"
/// display_value(&Value::Bool(true))     // → "True"
/// display_value(&Value::None)           // → "None"
/// ```
pub fn display_value(v: &Value) -> String {
    match v {
        Value::Int(i) => i.to_string(),
        Value::Float(f) => f.to_string(),
        Value::Bool(b) => if *b { "True" } else { "False" }.to_string(),
        Value::None => "None".to_string(),
        Value::Object(obj) => match &obj.data {
            ObjectData::String(s) => s.clone(),
            ObjectData::List { items } => {
                let items_ref = items.borrow();
                let contents: Vec<String> = items_ref.iter().map(display_value).collect();
                format!("[{}]", contents.join(", "))
            }
            ObjectData::Tuple { items } => {
                let contents: Vec<String> = items.iter().map(display_value).collect();
                if contents.len() == 1 {
                    format!("({},)", contents[0])
                } else {
                    format!("({})", contents.join(", "))
                }
            }
            ObjectData::Dict { map } => {
                let map_ref = map.borrow();
                let contents: Vec<String> = map_ref
                    .iter()
                    .map(|(k, v)| {
                        let key_str = match k {
                            DictKey::Int(i) => i.to_string(),
                            DictKey::String(s) => format!("\"{}\"", s),
                            DictKey::Bool(b) => if *b { "True" } else { "False" }.to_string(),
                        };
                        format!("{}: {}", key_str, display_value(v))
                    })
                    .collect();
                format!("{{{}}}", contents.join(", "))
            }
            ObjectData::Set { items } => {
                let items_ref = items.borrow();
                let contents: Vec<String> = items_ref.iter().map(|k| display_set_key(k)).collect();
                format!("{{{}}}", contents.join(", "))
            }
            ObjectData::TreeSet { items } => {
                let items_ref = items.borrow();
                let contents: Vec<String> = items_ref.iter().map(|k| display_set_key(k)).collect();
                format!("t{{{}}}", contents.join(", "))
            }
            ObjectData::UserClass { class_id, .. } => format!("<class user_{}>", class_id),
            ObjectData::UserInstance { class_id } => {
                format!("<instance of user_{}>", class_id)
            }
            ObjectData::BuiltinClass { class_type } => {
                format!("<class '{}'>", class_type.name())
            }
            ObjectData::BuiltinInstance { class_type, .. } => {
                format!("<{} object>", class_type.name())
            }
            ObjectData::UserFunction { func_id, .. } => {
                format!("<function lambda#{}>", func_id)
            }
        },
    }
}

/// Value의 타입 이름 반환
///
/// Python의 `type(x).__name__`과 유사합니다.
///
/// # Examples
///
/// ```ignore
/// type_name(&Value::Int(42))        // → "int"
/// type_name(&Value::Bool(true))     // → "bool"
/// type_name(&Value::None)           // → "NoneType"
/// ```
pub fn type_name(v: &Value) -> &'static str {
    match v {
        Value::Int(_) => "int",
        Value::Float(_) => "float",
        Value::Bool(_) => "bool",
        Value::None => "NoneType",
        Value::Object(obj) => match &obj.data {
            ObjectData::String(_) => "str",
            ObjectData::List { .. } => "list",
            ObjectData::Tuple { .. } => "tuple",
            ObjectData::Dict { .. } => "dict",
            ObjectData::Set { .. } => "set",
            ObjectData::TreeSet { .. } => "treeset",
            ObjectData::UserClass { .. } => "type",
            ObjectData::UserInstance { .. } => "instance",
            ObjectData::BuiltinClass { .. } => "type",
            ObjectData::BuiltinInstance { class_type, .. } => class_type.name(),
            ObjectData::UserFunction { .. } => "function",
        },
    }
}

/// Value 동등성 비교
///
/// Python의 `==` 연산자 의미론을 구현합니다.
///
/// # Rules
///
/// - 동일 타입 primitive 값: 값 비교
/// - String 객체: 문자열 내용 비교
/// - 다른 객체: 포인터 비교 (identity)
/// - 서로 다른 타입: `false`
pub fn eq_vals(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => x == y,
        (Value::Float(x), Value::Float(y)) => x == y,
        (Value::Int(x), Value::Float(y)) => (*x as f64) == *y,
        (Value::Float(x), Value::Int(y)) => *x == (*y as f64),
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::None, Value::None) => true,
        (Value::Object(x), Value::Object(y)) => {
            if Rc::ptr_eq(x, y) {
                return true;
            }
            match (&x.data, &y.data) {
                (ObjectData::String(s1), ObjectData::String(s2)) => s1 == s2,
                _ => false,
            }
        }
        _ => false,
    }
}

// ========== Object 생성 헬퍼 함수들 (make_*) ==========

/// String 객체 생성
pub fn make_string(s: String) -> Value {
    Value::Object(Rc::new(Object::new(TYPE_STR, ObjectData::String(s))))
}

/// List 객체 생성
pub fn make_list(items: Vec<Value>) -> Value {
    Value::Object(Rc::new(Object::new(
        TYPE_LIST,
        ObjectData::List {
            items: RefCell::new(items),
        },
    )))
}

/// Range 객체 생성
pub fn make_range(current: i64, stop: i64, step: i64) -> Value {
    Value::Object(Rc::new(Object::new(
        TYPE_RANGE,
        ObjectData::BuiltinInstance {
            class_type: BuiltinClassType::Range,
            data: BuiltinInstanceData::Range {
                current: RefCell::new(current),
                stop,
                step,
            },
        },
    )))
}

/// Dict 객체 생성
pub fn make_dict(map: HashMap<DictKey, Value>) -> Value {
    Value::Object(Rc::new(Object::new(
        TYPE_DICT,
        ObjectData::Dict {
            map: RefCell::new(map),
        },
    )))
}

/// SetKey를 문자열로 표시
fn display_set_key(key: &SetKey) -> String {
    match key {
        SetKey::Int(i) => i.to_string(),
        SetKey::String(s) => format!("\"{}\"", s),
        SetKey::Bool(b) => if *b { "True" } else { "False" }.to_string(),
    }
}

/// 사용자 정의 클래스 객체 생성
pub fn make_user_class(class_id: u16, methods: HashMap<String, u16>) -> Value {
    Value::Object(Rc::new(Object::new(
        TYPE_USER_START + class_id,
        ObjectData::UserClass { class_id, methods },
    )))
}

/// 사용자 정의 인스턴스 객체 생성
pub fn make_user_instance(class_id: u16) -> Value {
    Value::Object(Rc::new(Object::new_with_attrs(
        TYPE_USER_START + class_id,
        ObjectData::UserInstance { class_id },
    )))
}

/// Builtin 클래스 객체 생성
pub fn make_builtin_class(class_type: BuiltinClassType) -> Value {
    let type_id = match class_type {
        BuiltinClassType::Range => TYPE_RANGE,
        BuiltinClassType::List => TYPE_LIST,
        BuiltinClassType::Dict => TYPE_DICT,
        BuiltinClassType::Tuple => TYPE_TUPLE,
        BuiltinClassType::MapIter => TYPE_MAP_ITER,
        BuiltinClassType::FilterIter => TYPE_FILTER_ITER,
        BuiltinClassType::Set => TYPE_SET,
        BuiltinClassType::TreeSet => TYPE_TREESET,
    };
    Value::Object(Rc::new(Object::new(
        type_id,
        ObjectData::BuiltinClass { class_type },
    )))
}

