// ===== src/vm/builtins/str_methods.rs =====
pub mod str_methods {
    use super::*;
    // str methods implementation


    /// str() builtin 함수
    pub fn call(args: Vec<Value>) -> VmResult<Value> {
        // 인자 개수 검증
        if args.len() != 1 {
            return Err(err(
                VmErrorKind::ArityError {
                    expected: 1,
                    got: args.len(),
                },
                format!("str() takes exactly 1 argument ({} given)", args.len()),
            ));
        }

        let v = &args[0];
        Ok(make_string(display_value(v)))
    }

    // ========== String 메서드 구현들 ==========

    pub fn str_upper(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        if !args.is_empty() {
            return Err(err(
                VmErrorKind::ArityError {
                    expected: 0,
                    got: args.len(),
                },
                format!("str.upper() takes 0 arguments but {} given", args.len()),
            ));
        }
        let s = expect_string(receiver)?;
        Ok(make_string(s.to_uppercase()))
    }

    pub fn str_lower(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        if !args.is_empty() {
            return Err(err(
                VmErrorKind::ArityError {
                    expected: 0,
                    got: args.len(),
                },
                format!("str.lower() takes 0 arguments but {} given", args.len()),
            ));
        }
        let s = expect_string(receiver)?;
        Ok(make_string(s.to_lowercase()))
    }

    pub fn str_strip(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        if !args.is_empty() {
            return Err(err(
                VmErrorKind::ArityError {
                    expected: 0,
                    got: args.len(),
                },
                format!("str.strip() takes 0 arguments but {} given", args.len()),
            ));
        }
        let s = expect_string(receiver)?;
        Ok(make_string(s.trim().to_string()))
    }

    pub fn str_split(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        if args.len() > 1 {
            return Err(err(
                VmErrorKind::ArityError {
                    expected: 1,
                    got: args.len(),
                },
                format!(
                    "str.split() takes 0 or 1 argument, but {} given",
                    args.len()
                ),
            ));
        }
        let sep = match args.get(0) {
            None => " ",
            Some(value) if expect_string(value).is_ok() => expect_string(value)?,
            _ => {
                return Err(err(
                    VmErrorKind::TypeError("str.split"),
                    format!(
                        "str.split() takes 0 or 1 argument, but {} given",
                        args.len()
                    ),
                ));
            }
        };
        let s = expect_string(receiver)?;
        let result = s
            .split(sep)
            .map(|s| make_string(s.to_string()))
            .collect::<Vec<Value>>();
        Ok(make_list(result))
    }

    pub fn str_join(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        if args.len() != 1 {
            return Err(err(
                VmErrorKind::ArityError {
                    expected: 1,
                    got: args.len(),
                },
                format!("str.join() takes 1 argument but {} given", args.len()),
            ));
        }
        let s = expect_string(receiver)?;
        let list = expect_list(&args[0])?;
        let strings: Vec<String> = list
            .iter()
            .map(|v| expect_string(v).map(|s| s.to_string()))
            .collect::<Result<Vec<String>, _>>()?;
        let result = strings.join(s);
        Ok(make_string(result))
    }

    pub fn str_replace(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        if args.len() != 2 {
            return Err(err(
                VmErrorKind::ArityError {
                    expected: 2,
                    got: args.len(),
                },
                format!("str.replace() takes 2 arguments but {} given", args.len()),
            ));
        }
        let s = expect_string(receiver)?;
        let old = expect_string(&args[0])?;
        let new = expect_string(&args[1])?;
        Ok(make_string(s.replace(old, new)))
    }

    pub fn str_starts_with(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        if args.len() != 1 {
            return Err(err(
                VmErrorKind::ArityError {
                    expected: 1,
                    got: args.len(),
                },
                format!("str.startswith() takes 1 argument but {} given", args.len()),
            ));
        }
        let s = expect_string(receiver)?;
        let prefix = expect_string(&args[0])?;
        Ok(Value::Bool(s.starts_with(prefix)))
    }

    pub fn str_ends_with(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        if args.len() != 1 {
            return Err(err(
                VmErrorKind::ArityError {
                    expected: 1,
                    got: args.len(),
                },
                format!("str.endswith() takes 1 argument but {} given", args.len()),
            ));
        }
        let s = expect_string(receiver)?;
        let suffix = expect_string(&args[0])?;
        Ok(Value::Bool(s.ends_with(suffix)))
    }

    pub fn str_find(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        if args.len() != 1 {
            return Err(err(
                VmErrorKind::ArityError {
                    expected: 1,
                    got: args.len(),
                },
                format!("str.find() takes 1 argument but {} given", args.len()),
            ));
        }
        let s = expect_string(receiver)?;
        let substr = expect_string(&args[0])?;
        match s.find(substr) {
            Some(pos) => Ok(Value::Int(pos as i64)),
            None => Ok(Value::Int(-1)),
        }
    }

    pub fn str_count(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        if args.len() != 1 {
            return Err(err(
                VmErrorKind::ArityError {
                    expected: 1,
                    got: args.len(),
                },
                format!("str.count() takes 1 argument but {} given", args.len()),
            ));
        }
        let s = expect_string(receiver)?;
        let substr = expect_string(&args[0])?;
        let count = s.matches(substr).count();
        Ok(Value::Int(count as i64))
    }

    // ========== 매직 메서드 구현 ==========

    /// __add__: String + String (concatenation)
    pub fn str_add(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        let s1 = expect_string(receiver)?;
        let s2 = expect_string(&args[0])?;
        Ok(make_string(s1.to_string() + s2))
    }

    /// __mul__: String * Int (repetition)
    pub fn str_mul(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        let s = expect_string(receiver)?;
        let n = match &args[0] {
            Value::Int(n) => *n,
            _ => {
                return Err(err(
                    VmErrorKind::TypeError("str"),
                    "can't multiply string by non-int".into(),
                ));
            }
        };

        if n < 0 {
            Ok(make_string(String::new()))
        } else {
            Ok(make_string(s.repeat(n as usize)))
        }
    }

    /// __lt__: String < String
    pub fn str_lt(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        let s1 = expect_string(receiver)?;
        let s2 = expect_string(&args[0])?;
        Ok(Value::Bool(s1 < s2))
    }

    /// __le__: String <= String
    pub fn str_le(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        let s1 = expect_string(receiver)?;
        let s2 = expect_string(&args[0])?;
        Ok(Value::Bool(s1 <= s2))
    }

    /// __gt__: String > String
    pub fn str_gt(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        let s1 = expect_string(receiver)?;
        let s2 = expect_string(&args[0])?;
        Ok(Value::Bool(s1 > s2))
    }

    /// __ge__: String >= String
    pub fn str_ge(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        let s1 = expect_string(receiver)?;
        let s2 = expect_string(&args[0])?;
        Ok(Value::Bool(s1 >= s2))
    }

    /// __eq__: String == String
    pub fn str_eq(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        let s1 = expect_string(receiver)?;
        let s2 = expect_string(&args[0])?;
        Ok(Value::Bool(s1 == s2))
    }

    /// __ne__: String != String
    pub fn str_ne(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        let s1 = expect_string(receiver)?;
        let s2 = expect_string(&args[0])?;
        Ok(Value::Bool(s1 != s2))
    }
}

// ===== src/vm/builtins/float.rs =====
pub mod float {
    use super::*;

    /// float() builtin 함수
    pub fn call(args: Vec<Value>) -> VmResult<Value> {
        if args.len() != 1 {
            return Err(err(
                VmErrorKind::ArityError {
                    expected: 1,
                    got: args.len(),
                },
                format!("float() takes exactly 1 argument ({} given)", args.len()),
            ));
        }

        let arg = &args[0];
        match arg {
            Value::Int(i) => Ok(Value::Float(*i as f64)),
            Value::Float(f) => Ok(Value::Float(*f)),
            Value::Bool(b) => Ok(Value::Float(if *b { 1.0 } else { 0.0 })),
            Value::Object(obj) => {
                // String 객체를 Float로 변환 시도
                match &obj.data {
                    ObjectData::String(s) => s.trim().parse::<f64>().map(Value::Float).map_err(|_| {
                        err(
                            VmErrorKind::TypeError("float"),
                            format!("could not convert string to float: '{}'", s),
                        )
                    }),
                    _ => Err(err(
                        VmErrorKind::TypeError("float"),
                        format!(
                            "float() argument must be a string or a number, not '{}'",
                            type_name(arg)
                        ),
                    )),
                }
            }
            Value::None => Err(err(
                VmErrorKind::TypeError("float"),
                "float() argument must be a string or a number, not 'NoneType'".to_string(),
            )),
        }
    }

    pub fn register_type() -> TypeDef {
        TypeDef::new("float", TypeFlags::IMMUTABLE)
    }

    // ========== 매직 메서드 구현 ==========

    pub fn float_add(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        let (a, b) = (expect_float(receiver)?, expect_float(&args[0])?);
        Ok(Value::Float(a + b))
    }

    pub fn float_sub(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        let (a, b) = (expect_float(receiver)?, expect_float(&args[0])?);
        Ok(Value::Float(a - b))
    }

    pub fn float_mul(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        let (a, b) = (expect_float(receiver)?, expect_float(&args[0])?);
        Ok(Value::Float(a * b))
    }

    pub fn float_true_div(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        let (a, b) = (expect_float(receiver)?, expect_float(&args[0])?);
        Ok(Value::Float(a / b))
    }

    pub fn float_floor_div(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        let (a, b) = (expect_float(receiver)?, expect_float(&args[0])?);
        if b == 0.0 {
            return Err(err(VmErrorKind::ZeroDivision, "division by zero".into()));
        }
        Ok(Value::Float((a / b).floor()))
    }

    pub fn float_mod(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        let (a, b) = (expect_float(receiver)?, expect_float(&args[0])?);
        if b == 0.0 {
            return Err(err(VmErrorKind::ZeroDivision, "modulo by zero".into()));
        }
        Ok(Value::Float(a % b))
    }

    pub fn float_neg(receiver: &Value, _args: Vec<Value>) -> VmResult<Value> {
        Ok(Value::Float(-expect_float(receiver)?))
    }

    pub fn float_pos(receiver: &Value, _args: Vec<Value>) -> VmResult<Value> {
        Ok(Value::Float(expect_float(receiver)?))
    }

    pub fn float_lt(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        let (a, b) = (expect_float(receiver)?, expect_float(&args[0])?);
        Ok(Value::Bool(a < b))
    }

    pub fn float_le(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        let (a, b) = (expect_float(receiver)?, expect_float(&args[0])?);
        Ok(Value::Bool(a <= b))
    }

    pub fn float_gt(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        let (a, b) = (expect_float(receiver)?, expect_float(&args[0])?);
        Ok(Value::Bool(a > b))
    }

    pub fn float_ge(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        let (a, b) = (expect_float(receiver)?, expect_float(&args[0])?);
        Ok(Value::Bool(a >= b))
    }

    pub fn float_eq(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        let (a, b) = (expect_float(receiver)?, expect_float(&args[0])?);
        Ok(Value::Bool(a == b))
    }

    pub fn float_ne(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        let (a, b) = (expect_float(receiver)?, expect_float(&args[0])?);
        Ok(Value::Bool(a != b))
    }
}

// ===== src/vm/builtins/len.rs =====
pub mod len {
    use super::*;

    /// len() builtin 함수
    pub fn call(args: Vec<Value>) -> VmResult<Value> {
        if args.len() != 1 {
            return Err(err(
                VmErrorKind::ArityError {
                    expected: 1,
                    got: args.len(),
                },
                format!("len() takes exactly 1 argument ({} given)", args.len()),
            ));
        }

        let v = &args[0];
        match v {
            Value::Object(obj) => {
                match &obj.data {
                    ObjectData::String(s) => Ok(Value::Int(s.chars().count() as i64)),
                    ObjectData::List { items } => Ok(Value::Int(items.borrow().len() as i64)),
                    ObjectData::Tuple { items } => Ok(Value::Int(items.len() as i64)),
                    ObjectData::Dict { map } => Ok(Value::Int(map.borrow().len() as i64)),
                    _ => Err(err(
                        VmErrorKind::TypeError("len"),
                        format!("object of type '{}' has no len()", type_name(v)),
                    )),
                }
            }
            _ => Err(err(
                VmErrorKind::TypeError("len"),
                format!("object of type '{}' has no len()", type_name(v)),
            )),
        }
    }
}

// ===== src/vm/builtins/range.rs =====
pub mod range {
    use super::*;

    /// range() 생성자
    ///
    /// range(stop)
    /// range(start, stop)
    /// range(start, stop, step)
    ///
    /// ```python
    /// for i in range(5):        # 0, 1, 2, 3, 4
    ///     print(i)
    ///
    /// for i in range(2, 5):     # 2, 3, 4
    ///     print(i)
    ///
    /// for i in range(0, 10, 2): # 0, 2, 4, 6, 8
    ///     print(i)
    /// ```
    pub fn create_range(args: Vec<Value>) -> VmResult<Value> {
        // Note: Arity is usually validated by semantic analyzer (1-3 args)
        // However, we still check at runtime for direct calls (e.g., in tests or dynamic scenarios)
        let (start, stop, step) = match args.len() {
            1 => {
                // range(stop)
                let stop = extract_int(&args[0])?;
                (0, stop, 1)
            }
            2 => {
                // range(start, stop)
                let start = extract_int(&args[0])?;
                let stop = extract_int(&args[1])?;
                (start, stop, 1)
            }
            3 => {
                // range(start, stop, step)
                let start = extract_int(&args[0])?;
                let stop = extract_int(&args[1])?;
                let step = extract_int(&args[2])?;

                if step == 0 {
                    return Err(err(
                        VmErrorKind::TypeError("range"),
                        "range() step argument must not be zero".into(),
                    ));
                }

                (start, stop, step)
            }
            n => {
                // Runtime arity check for direct calls (e.g., tests, dynamic code)
                return Err(err(
                    VmErrorKind::ArityError {
                        expected: 3,
                        got: n,
                    },
                    format!("range() takes 1 to 3 arguments ({} given)", n),
                ));
            }
        };

        Ok(make_range(start, stop, step))
    }

    /// Value에서 int 추출
    fn extract_int(v: &Value) -> VmResult<i64> {
        match v {
            Value::Int(i) => Ok(*i),
            _ => Err(err(
                VmErrorKind::TypeError("int"),
                format!("range() argument must be int, not '{}'", type_name(v)),
            )),
        }
    }

    // ========== Range 메서드 구현들 ==========

    pub fn range_iter(receiver: &Value, _args: Vec<Value>) -> VmResult<Value> {
        // Range는 자기 자신이 iterator (Python과 동일)
        Ok(receiver.clone())
    }

    pub fn range_has_next(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        if !args.is_empty() {
            return Err(err(
                VmErrorKind::ArityError {
                    expected: 0,
                    got: args.len(),
                },
                format!(
                    "range.__has_next__() takes 0 arguments but {} given",
                    args.len()
                ),
            ));
        }

        match receiver {
            Value::Object(obj) => match &obj.data {
                ObjectData::BuiltinInstance {
                    data:
                        BuiltinInstanceData::Range {
                            current,
                            stop,
                            step,
                        },
                    ..
                } => {
                    let curr = *current.borrow();
                    let has_next = if *step > 0 {
                        curr < *stop
                    } else if *step < 0 {
                        curr > *stop
                    } else {
                        false // step == 0은 에러이지만, 일단 false 반환
                    };
                    Ok(Value::Bool(has_next))
                }
                _ => Err(err(
                    VmErrorKind::TypeError("range"),
                    "expected Range object".into(),
                )),
            },
            _ => Err(err(
                VmErrorKind::TypeError("range"),
                "expected Range".into(),
            )),
        }
    }

    pub fn range_next(receiver: &Value, args: Vec<Value>) -> VmResult<Value> {
        if !args.is_empty() {
            return Err(err(
                VmErrorKind::ArityError {
                    expected: 0,
                    got: args.len(),
                },
                format!(
                    "range.__next__() takes 0 arguments but {} given",
                    args.len()
                ),
            ));
        }

        match receiver {
            Value::Object(obj) => match &obj.data {
                ObjectData::BuiltinInstance {
                    data:
                        BuiltinInstanceData::Range {
                            current,
                            stop,
                            step,
                        },
                    ..
                } => {
                    let mut curr_mut = current.borrow_mut();
                    let value = *curr_mut;
                    *curr_mut += *step;
                    Ok(Value::Int(value))
                }
                _ => Err(err(
                    VmErrorKind::TypeError("range"),
                    "expected Range object".into(),
                )),
            },
            _ => Err(err(
                VmErrorKind::TypeError("range"),
                "expected Range".into(),
            )),
        }
    }

    /// range 타입 정의 등록
    pub fn register_type() -> TypeDef {
        TypeDef::new("range", TypeFlags::IMMUTABLE | TypeFlags::ITERABLE).with_methods(vec![
            (
                "__iter__",
                MethodImpl::Native {
                    func: NativeMethod::RangeIter,
                    arity: Arity::Exact(0),
                },
            ),
            (
                "__has_next__",
                MethodImpl::Native {
                    func: NativeMethod::RangeHasNext,
                    arity: Arity::Exact(0),
                },
            ),
            (
                "__next__",
                MethodImpl::Native {
                    func: NativeMethod::RangeNext,
                    arity: Arity::Exact(0),
                },
            ),
        ])
    }
}

